INSERT INTO `locales_achievement_reward` (`entry`,`subject_loc8`,`text_loc8`) VALUES (5866,'Дар верховного друида','Никогда больше Хиджал не ощутит на себе бескрайнюю силу легионов огня. Никогда больше смертные расы не склонятся перед слугами Рагнароса.$b$bБлагодаря тебе они будут трепетать услышав НАШИ имена.$b$bТвоя отвага помогла нам низвергнуть Повелителя огня. Именно ты собрал армию могущественных союзников со всего Калимдора. ВЫ сразились со слугами Рагнароса и... победили. Прими нашу искреннюю благодарность.') ON DUPLICATE KEY UPDATE `subject_loc8`=IF(`subject_loc8` IS NULL OR `subject_loc8`='','Дар верховного друида',`subject_loc8`), `text_loc8`=IF(`text_loc8` IS NULL OR `text_loc8`='','Никогда больше Хиджал не ощутит на себе бескрайнюю силу легионов огня. Никогда больше смертные расы не склонятся перед слугами Рагнароса.$b$bБлагодаря тебе они будут трепетать услышав НАШИ имена.$b$bТвоя отвага помогла нам низвергнуть Повелителя огня. Именно ты собрал армию могущественных союзников со всего Калимдора. ВЫ сразились со слугами Рагнароса и... победили. Прими нашу искреннюю благодарность.',`text_loc8`);
